1	{
2	  "$schema": "http://json-schema.org/draft-07/schema#",
3	  "$id": "https://github.com/LeoLin990405/civagent/schemas/regime-topology.schema.json",
4	  "title": "CivAgent regime topology",
5	  "description": "Explicit governance graph for one regime (regimes/<region>/<id>/topology.json). Nodes are roles from the regime's IDENTITY.md role mapping table; edges are typed instruction/information flows between them. This makes the 57 regimes a computable design space.",
6	  "type": "object",
7	  "required": ["schema_version", "regime", "mode", "nodes", "edges"],
8	  "additionalProperties": true,
9	  "properties": {
10	    "schema_version": { "type": "string", "description": "Topology schema version, e.g. \"1.0\"." },
11	    "regime": {
12	      "type": "string",
13	      "pattern": "^[a-z0-9-]+/[a-z0-9-]+$",
14	      "description": "region/regime-id, e.g. china/tang. Must match the directory the file lives in."
15	    },
16	    "mode": {
17	      "type": "string",
18	      "enum": ["centralized", "checks-and-balances", "democratic", "dual-track", "federation", "theocratic"],
19	      "description": "Orchestration mode; must correspond to metadata.json's orchestrationPattern (after alias normalization)."
20	    },
21	    "nodes": {
22	      "type": "array",
23	      "minItems": 1,
24	      "description": "Role nodes. The set of ids must equal the Agent ID set in the regime's IDENTITY.md role mapping table.",
25	      "items": {
26	        "type": "object",
27	        "required": ["id", "label", "functional_role"],
28	        "additionalProperties": true,
29	        "properties": {
30	          "id": { "type": "string", "minLength": 1, "description": "Agent ID exactly as in IDENTITY.md (e.g. zhongshu-sheren)." },
31	          "label": { "type": "string", "minLength": 1, "description": "Human-readable historical role name (e.g. 中书舍人)." },
32	          "functional_role": {
33	            "type": "string",
34	            "enum": ["coordinator", "engineering", "review", "research", "data", "devops", "content", "legal", "management"],
35	            "description": "Canonical functional role (same 9-value vocabulary as engine/regime-to-cc.mjs ROLE_MODEL_MAP)."
36	          },
37	          "kind": {
38	            "type": ["string", "null"],
39	            "enum": ["agent", "gate", "checkpoint", "router", null],
40	            "description": "Structural node kind. Optional with default 'agent' (the historical baseline: every node is an LLM-backed role). 'agent' = calls the model and produces content (the only kind for all 57 pre-typing regimes). 'gate' = deterministic gate: no model discretion, a rule decides pass/block (e.g. the [VETO] hard-abort mechanism). 'checkpoint' = human checkpoint: control is handed back to the operator. 'router' = pure fan-out dispatcher: routes work, produces no content. Omitted/null is always valid and means 'agent'."
41	          }
42	        }
43	      }
44	    },
45	    "edges": {
46	      "type": "array",
47	      "description": "Typed directed flows between role nodes.",
48	      "items": {
49	        "type": "object",
50	        "required": ["from", "to", "kind"],
51	        "additionalProperties": true,
52	        "properties": {
53	          "from": { "type": "string", "description": "Source node id." },
54	          "to": { "type": "string", "description": "Target node id." },
55	          "kind": {
56	            "type": "string",
57	            "enum": ["command", "review", "info", "veto"],
58	            "description": "command = instruction flow / reporting; review = checks / auditing; info = information sharing; veto = rejection / 封驳."
59	          },
60	          "note": { "type": "string", "description": "Optional provenance note (e.g. which IDENTITY.md flow step justifies this edge)." }
61	        }
62	      }
63	    }
64	  },
65	  "examples": [
66	    {
67	      "schema_version": "1.0",
68	      "regime": "china/qin",
69	      "mode": "centralized",
70	      "nodes": [
71	        { "id": "emperor", "label": "皇帝", "functional_role": "coordinator" },
72	        { "id": "chengxiang", "label": "丞相", "functional_role": "management" },
73	        { "id": "yushi-censor", "label": "御史大夫", "functional_role": "review" }
74	      ],
75	      "edges": [
76	        { "from": "emperor", "to": "chengxiang", "kind": "command" },
77	        { "from": "yushi-censor", "to": "chengxiang", "kind": "review", "note": "御史大夫全程监察百官" }
78	      ]
79	    }
80	  ]
81	}
